// symposium:managed
/**
 * symposium hook bridge for Pi.
 *
 * Generated by symposium (`src/agents/assets/pi-extension.ts`), which owns this
 * file: `cargo agents init` / `cargo agents sync` overwrites it, and
 * `cargo agents sync` in another workspace or `cargo agents init --remove-agent
 * pi` deletes it. Edits here are lost; put your own extensions in a different
 * file.
 *
 * Pi has no shell hooks, so this extension is the bridge: it spawns
 * `cargo-agents hook pi <event>` with the event payload on stdin, and applies
 * the JSON symposium writes to stdout to the running session.
 *
 * Every path is fail-open. If the binary is missing, slow, or prints something
 * unparseable, the tool call runs and the prompt proceeds: symposium guides the
 * agent, it does not gate it.
 */
import { spawn } from "node:child_process";
import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";

/** Override for a symposium built from a working copy, or a non-PATH install. */
const SYMPOSIUM_BIN = process.env.SYMPOSIUM_PI_HOOK_BIN || "cargo-agents";

/** Tool calls and prompts wait for a reply, so they get a short leash. */
const QUICK_TIMEOUT_MS = 10_000;
/** SessionStart also refreshes plugin sources, which may touch the network. */
const SESSION_TIMEOUT_MS = 60_000;

type HookJson = Record<string, unknown>;

interface HookResult {
  ok: boolean;
  json?: HookJson;
}

function debug(message: string): void {
  if (process.env.SYMPOSIUM_PI_DEBUG) process.stderr.write(`[symposium] ${message}\n`);
}

/**
 * Run one symposium hook. Never rejects: a hook that cannot run is a hook with
 * nothing to say.
 */
function runHook(event: string, payload: HookJson, timeoutMs: number): Promise<HookResult> {
  return new Promise((resolve) => {
    let child;
    try {
      child = spawn(SYMPOSIUM_BIN, ["hook", "pi", event], { stdio: ["pipe", "pipe", "pipe"] });
    } catch (error) {
      debug(`${event}: spawn failed: ${error}`);
      resolve({ ok: false });
      return;
    }

    let stdout = "";
    let settled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    const finish = (result: HookResult) => {
      if (settled) return;
      settled = true;
      if (timer !== undefined) clearTimeout(timer);
      resolve(result);
    };

    timer = setTimeout(() => {
      debug(`${event}: timed out after ${timeoutMs}ms`);
      try {
        child.kill("SIGKILL");
      } catch {
        // Already gone.
      }
      finish({ ok: false });
    }, timeoutMs);

    child.stdout?.on("data", (chunk) => {
      stdout += chunk;
    });
    child.on("error", (error) => {
      debug(`${event}: ${error}`);
      finish({ ok: false });
    });
    child.on("close", (code) => {
      const text = stdout.trim();
      if (!text) {
        if (code !== 0 && code !== null) debug(`${event}: exit ${code}, no output`);
        return finish({ ok: true });
      }
      try {
        const parsed = JSON.parse(text);
        finish({ ok: true, json: parsed && typeof parsed === "object" ? parsed : undefined });
      } catch {
        // Anything but JSON (a stray log line, an update notice) means symposium
        // had nothing to apply. Pi would show raw text to the user, so drop it.
        debug(`${event}: output was not JSON`);
        finish({ ok: false });
      }
    });

    try {
      child.stdin?.write(JSON.stringify(payload));
      child.stdin?.end();
    } catch (error) {
      debug(`${event}: write failed: ${error}`);
      try {
        child.kill("SIGKILL");
      } catch {
        // Already gone.
      }
      finish({ ok: false });
    }
  });
}

/** `session_id` / `cwd`, which symposium uses to find the workspace and to key sessions. */
function base(ctx: ExtensionContext): HookJson {
  let sessionId: string | undefined;
  try {
    sessionId = ctx.sessionManager.getSessionId();
  } catch {
    sessionId = undefined;
  }
  const payload: HookJson = { cwd: ctx.cwd };
  if (sessionId !== undefined) payload.session_id = sessionId;
  return payload;
}

function contextOf(result: HookResult): string | undefined {
  const value = result.json?.additionalContext;
  if (typeof value !== "string") return undefined;
  return value.trim() ? value : undefined;
}

/**
 * Resolve `hook` if it finishes within `ms`, else resolve `null` and let the
 * hook keep running. `runHook` always resolves; it never rejects.
 */
function settleWithin(hook: Promise<HookResult>, ms: number): Promise<HookResult | null> {
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve(null), ms);
    hook.then((result) => {
      clearTimeout(timer);
      resolve(result);
    });
  });
}

export default function (pi: ExtensionAPI): void {
  /**
   * Pi's `session_start` is notification-only: nothing it returns reaches the
   * conversation. So session-start context waits here and is injected on the
   * first run, where `before_agent_start` can add a message.
   */
  let pending: string[] = [];

  /**
   * The SessionStart hook in flight. Pi **awaits** `session_start` handlers, and
   * symposium's SessionStart runs a full auto-sync (~2 s warm here; on a stalled
   * network it can run to `SESSION_TIMEOUT_MS`). Awaiting that here would put it
   * in front of the TUI, so the hook is started here and awaited by the first
   * run instead: latency the user asked for by sending a message, rather than a
   * startup stall nobody asked for.
   */
  let starting: Promise<HookResult> | null = null;

  pi.on("session_start", (event, ctx) => {
    // `/reload` re-fires session_start for a resource reload rather than a new
    // session; injecting again would repeat the same context in one conversation.
    if (event.reason === "reload") return;
    // One dispatch per session: a second start while the first is in flight (or
    // after the first run already collected it) would only repeat the same work.
    if (starting) return;

    starting = runHook(
      "session-start",
      { hook_event_name: "SessionStart", ...base(ctx) },
      SESSION_TIMEOUT_MS,
    );
  });

  pi.on("before_agent_start", async (event, ctx) => {
    const chunks = pending.splice(0, pending.length);

    if (starting) {
      // Wait no longer than a prompt hook would have run. If the sync is still
      // going, the session context stays in flight for the next run instead of
      // holding the user's first message for the hook's full timeout.
      const settled = await settleWithin(starting, QUICK_TIMEOUT_MS);
      if (settled) {
        starting = null;
        const context = contextOf(settled);
        if (context && !chunks.includes(context)) chunks.push(context);
      }
    }

    if (event.messageType === "user") {
      const result = await runHook(
        "user-prompt-submit",
        {
          hook_event_name: "UserPromptSubmit",
          prompt: event.prompt ?? "",
          message_type: event.messageType,
          ...base(ctx),
        },
        QUICK_TIMEOUT_MS,
      );
      const context = contextOf(result);
      if (context && !chunks.includes(context)) chunks.push(context);
    }

    if (chunks.length === 0) return undefined;

    // A custom message reaches the model without appearing in the transcript as
    // a symposium notice, which is what every other agent's `additionalContext`
    // does.
    return {
      message: {
        customType: "symposium",
        content: chunks.join("\n\n"),
        display: false,
        details: { fragments: chunks.length },
      },
    };
  });

  pi.on("tool_call", async (event, ctx) => {
    const result = await runHook(
      "pre-tool-use",
      {
        hook_event_name: "PreToolUse",
        tool_name: event.toolName,
        tool_input: event.input as unknown,
        ...base(ctx),
      },
      QUICK_TIMEOUT_MS,
    );
    const json = result.json;
    if (!json) return undefined;

    const updated = json.updatedInput;
    if (updated && typeof updated === "object" && !Array.isArray(updated)) {
      // Pi reads rewritten arguments from `event.input` mutated in place and
      // does not re-validate them, so this is the only place they can land.
      const target = event.input as unknown as Record<string, unknown>;
      for (const key of Object.keys(target)) delete target[key];
      Object.assign(target, updated as Record<string, unknown>);
    }

    if (json.block === true) {
      const reason = json.reason;
      return {
        block: true,
        reason:
          typeof reason === "string" && reason.trim()
            ? reason
            : "blocked by a symposium plugin",
      };
    }
    return undefined;
  });

  pi.on("tool_result", async (event, ctx) => {
    const result = await runHook(
      "post-tool-use",
      {
        hook_event_name: "PostToolUse",
        tool_name: event.toolName,
        tool_input: event.input,
        tool_response: { content: event.content, isError: event.isError },
        ...base(ctx),
      },
      QUICK_TIMEOUT_MS,
    );
    const context = contextOf(result);
    if (!context) return undefined;

    // Returning `content` replaces it, so the original blocks come back with the
    // context appended; `structuredContent` must be returned too or Pi drops it.
    return {
      content: [...event.content, { type: "text" as const, text: context }],
      ...(event.structuredContent === undefined
        ? {}
        : { structuredContent: event.structuredContent }),
    };
  });

  pi.on("agent_end", async (_event, ctx) => {
    // Notification only: a Stop hook's output reaches no one, so its exit is
    // ignored.
    await runHook("stop", { hook_event_name: "Stop", ...base(ctx) }, QUICK_TIMEOUT_MS);
  });
}
